      field.input.addEventListener('blur', () => {
        if (attemptedSubmit) {
          if (field === fields.fullName) validateFullName();
          if (field === fields.email) validateEmail();
          if (field === fields.phone) validatePhone();
        }
      });

      field.input.addEventListener('input', () => {
        if (attemptedSubmit) {
          if (field === fields.fullName) validateFullName();
          if (field === fields.email) validateEmail();
          if (field === fields.phone) validatePhone();
        }
      });
    });

