  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content" class="page-shell">
    <header class="hero">
      <p class="eyebrow">Support</p>
      <h1>Contact our team</h1>
      <p class="lead">Send us your details and we’ll route your request to the right support specialist.</p>
    </header>

    <div class="layout">
      <section class="card form-card">
        <form id="contact-form" novalidate>
          <div class="form-grid">
            <div class="form-field">
              <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
              <input
                id="full-name"
                name="fullName"
                type="text"
                autocomplete="name"
                required
                aria-describedby="full-name-error"
              >
              <div class="error-shell">
                <p class="error-text" id="full-name-error" hidden></p>
              </div>
            </div>

            <div class="form-field">
              <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
              <input
                id="email-address"
                name="email"
                type="email"
                autocomplete="email"
                required
                aria-describedby="email-error"
              >
              <div class="error-shell">
                <p class="error-text" id="email-error" hidden></p>
              </div>
            </div>

            <div class="form-field">
              <label for="phone-number">Phone number</label>
              <input
                id="phone-number"
                name="phone"
                type="tel"
                inputmode="tel"
                autocomplete="tel"
                aria-describedby="phone-help phone-error"
              >
              <p class="help-text" id="phone-help">Format: +1 555 123 4567 or 555-123-4567. Leave blank if you prefer email.</p>
              <div class="error-shell">
                <p class="error-text" id="phone-error" hidden></p>
              </div>
            </div>

            <div class="actions">
              <button class="button" type="submit">Send message</button>
              <p class="note">Required fields are marked with an asterisk.</p>
            </div>
          </div>

          <p id="form-status" class="status" role="status" aria-live="polite" hidden></p>
        </form>
      </section>

      <aside class="card side-card" aria-labelledby="support-hours-title">
        <h2 id="support-hours-title">What happens next</h2>
        <p class="note">A support specialist reviews your message and follows up by email or phone.</p>
        <ul class="support-list">
          <li>
            <strong>Response window</strong>
            <span>Usually within one business day.</span>
          </li>
          <li>
            <strong>Best contact details</strong>
            <span>Use your preferred email so we can reply quickly.</span>
          </li>
          <li>
            <strong>Phone format</strong>
            <span>Include country code if you’re outside the U.S.</span>
          </li>
        </ul>
      </aside>
    </div>
  </main>

  <script>
    const form = document.getElementById('contact-form');
    const status = document.getElementById('form-status');
    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        message: 'Error: Enter your full name.'
      },
      email: {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-error'),
        message: 'Error: Enter a valid email address.'
      },
      phone: {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-error'),
        message: 'Error: Use a phone number like +1 555 123 4567.'
      }
    };

    const phonePattern = /^\+?[0-9()\-\s.]{7,}$/;
    let attemptedSubmit = false;

    function updateFieldState(field, isValid, message = '') {
      if (isValid) {
        field.input.removeAttribute('aria-invalid');
      } else {
        field.input.setAttribute('aria-invalid', 'true');
      }
      field.error.hidden = isValid;
      field.error.textContent = isValid ? '' : message;
    }

    function validateFullName() {
      const value = fields.fullName.input.value.trim();
      const valid = value.length > 0;
      updateFieldState(fields.fullName, valid, fields.fullName.message);
      return valid;
    }

    function validateEmail() {
      const input = fields.email.input;
      const valid = input.value.trim().length > 0 && input.validity.valid;
      updateFieldState(fields.email, valid, fields.email.message);
      return valid;
    }

    function validatePhone() {
      const value = fields.phone.input.value.trim();
      const valid = value === '' || phonePattern.test(value);
      updateFieldState(fields.phone, valid, fields.phone.message);
      return valid;
    }

    function validateAll() {
      const results = [validateFullName(), validateEmail(), validatePhone()];
      return results.every(Boolean);
    }

    function firstInvalidField() {
      return Object.values(fields).find((field) => field.input.getAttribute('aria-invalid') === 'true');
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener('blur', () => {
        if (attemptedSubmit) {
          if (field === fields.fullName) validateFullName();
          if (field === fields.email) validateEmail();
          if (field === fields.phone) validatePhone();
        }
      });

      field.input.addEventListener('input', () => {
        if (attemptedSubmit) {
          if (field === fields.fullName) validateFullName();
          if (field === fields.email) validateEmail();
          if (field === fields.phone) validatePhone();
        }
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      attemptedSubmit = true;
      status.hidden = true;
      status.textContent = '';

      const isValid = validateAll();

      if (!isValid) {
        const invalid = firstInvalidField();
        invalid?.input.focus();
        return;
      }

      status.textContent = 'Thanks — your message is ready to send.';
      status.hidden = false;
      form.reset();

      Object.values(fields).forEach((field) => {
        field.input.removeAttribute('aria-invalid');
        field.error.hidden = true;
        field.error.textContent = '';
      });

      attemptedSubmit = false;
      fields.fullName.input.focus();
    });
  </script>
